struct Circle {
    vec2 pos;
    float rad;
    vec3 color;
};

float sdf_circle(in vec2 pos, in float rad, in vec2 point){
    return length(pos - point) - rad;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;

    float aspect = iResolution.x / iResolution.y;
    uv.x *= aspect;

    vec2 mouse = iMouse.xy / iResolution.xy;
    mouse.x *= aspect;

    vec3 light = vec3(0.8);
    vec3 shadow = vec3(0.2);
    vec3 col = shadow;

    Circle cir1;
    cir1.pos = vec2(0.3 * aspect, 0.5);
    cir1.rad = 0.08;
    cir1.color = vec3(0.5);

    Circle cir2;
    cir2.pos = vec2(0.8 * aspect, 0.5);
    cir2.rad = 0.2;
    cir2.color = vec3(0.5);

    //precheck if we are inside circle
    float tester;
    tester = sdf_circle(cir1.pos, cir1.rad, uv);
    if (tester < 0.){
        fragColor = vec4(cir1.color, 1.);
        return;
    }
    tester = sdf_circle(cir2.pos, cir2.rad, uv);
    if (tester < 0.){
        fragColor = vec4(cir2.color, 1.);
        return;
    }




    // Calculate distance to mouse
    // it is the max distance to light source as mouse is light source
    float max_dist = length(uv - mouse);
    float dist = 0.;


    vec2 direction = normalize(mouse - uv);

    int max_steps = 100;
    float epsilon = 0.001;

    // Marching loop
    for (int i = 0; i < max_steps; i++) {
        vec2 current = uv + (direction * dist); // current position, used to sample 
        float sdf1 = sdf_circle(cir1.pos, cir1.rad, current);
        float sdf2 = sdf_circle(cir2.pos, cir2.rad, current);

        float sdf = min(sdf1, sdf2);


        // traveling more than max distance or equal to it mean we reached light
        if (dist >= max_dist) {
            col = light;
            break;
        }


        // hit a surface. exit
        if (sdf < epsilon) {
            col = shadow;
            break;
        }

        dist += sdf; // Accumulate distance based on the SDF
    }




    // Output the final color
    fragColor = vec4(col, 1.0);
}
